  font-family: var(--font-serif);
  line-height: 1.25;
  margin: calc(var(--space) * 2) 0 calc(var(--space) * 0.5);
}

/* ===== Pull quotes ===== */
.pull-quote {
  position: relative;
  margin: calc(var(--space) * 2) 0;
  padding: var(--space) 0 var(--space) 1.5rem;
  border-left: 4px solid var(--color-accent);
}

.pull-quote p {
  font-family: var(--font-serif);
  font-size: 1.5em;
  font-style: italic;
