  line-height: 1;
  font-style: normal;
  color: var(--color-accent);
  opacity: 0.15;
  pointer-events: none;
}

.pull-quote cite {
  display: block;
  margin-top: 1rem;
  font-family: var(--font-sans);
  font-size: var(--text-sm);
  font-style: normal;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--color-text-muted);
}

.pull-quote cite::before {
  content: "— ";
}

/* Floated variants on wide screens: break out of the text column */
@media (min-width: 1000px) {
  .pull-quote--left,
  .pull-quote--right {
    width: 45%;
    margin-top: 0.5rem;
    margin-bottom: 1rem;
    font-size: var(--text-lg);
  }

  .pull-quote--left {
    float: left;
    margin-left: -12%;
    margin-right: 2rem;
  }

  .pull-quote--right {
    float: right;
    margin-right: -12%;
    margin-left: 2rem;
  }

  /* Full-bleed-ish centered variant */
  .pull-quote--wide {
    margin-left: -10%;
    margin-right: -10%;
    padding-left: 2rem;
    padding-right: 2rem;
    text-align: center;
    font-size: calc(var(--text-xl) * 1.15);
  }

  .pull-quote--wide::before {
    left: 50%;
    transform: translateX(-50%);
  }
}

/* Contain floats so they don't spill below the post */
.post-body::after {
  content: "";
  display: table;
  clear: both;
}

/* ---------- Dark mode ---------- */
@media (prefers-color-scheme: dark) {
  :root {
    --color-text: #d6d9dd;
    --color-text-muted: #9aa1a9;
    --color-heading: #f2f3f5;
    --color-accent: #e8775f;
    --color-accent-soft: #3a2621;
    --color-border: #33373d;
    --color-bg: #16181b;
    --color-link: #e8775f;
    --color-link-hover: #f39a86;
  }

  .post-body code {
    background: #24272b;
  }
}

/* ---------- Print ---------- */
@media print {
  body {
    background: #fff;
    color: #000;
  }

  .post {
    max-width: none;
    padding: 0;
  }

  .pull-quote {
    float: none !important;
    width: auto !important;
    margin: 1.5rem 0 !important;
    break-inside: avoid;
  }

  .post-body a::after {
    content: " (" attr(href) ")";
    font-size: 0.85em;
    color: #555;
  }
}
