  font-family: inherit;
  color: var(--text);
  background: var(--white);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  transition: border-color var(--transition), box-shadow var(--transition);
}

.form-group input::placeholder {
  color: #9ca3af;
}

.form-group input:hover {
  border-color: #9ca3af;
}

