  color: var(--text-muted);
  text-align: center;
  margin-bottom: 2rem;
}

/* ===== Form Groups ===== */
.form-group {
  margin-bottom: 1.25rem;
}

.form-group label {
  display: block;
  font-size: 0.875rem;
  font-weight: 600;
  margin-bottom: 0.4rem;
}

/* ===== Inputs ===== */
.form-group input {
  width: 100%;
  padding: 0.75rem 1rem;
  font-size: 1rem;
  font-family: inherit;
  color: var(--text);
  background: var(--white);
  border: 1px solid var(--border);
