  display: flex;
  align-items: center;
  gap: 0.5rem;
  color: var(--text-muted);
  cursor: pointer;
}

.checkbox-label input[type="checkbox"] {
  width: 1rem;
  height: 1rem;
  accent-color: var(--primary);
  cursor: pointer;
}

/* ===== Links ===== */
.forgot-link,
.signup-text a {
  color: var(--primary);
  text-decoration: none;
  font-weight: 500;
  transition: color var(--transition);
}

.forgot-link:hover,
.signup-text a:hover {
  color: var(--primary-hover);
  text-decoration: underline;
}

.forgot-link:focus-visible,
.signup-text a:focus-visible {
  outline: 2px solid var(--primary);
  outline-offset: 2px;
  border-radius: 2px;
}

/* ===== Submit Button ===== */
.submit-btn {
  width: 100%;
  padding: 0.85rem 1rem;
  font-size: 1rem;
  font-weight: 600;
  font-family: inherit;
  color: var(--white);
  background: var(--primary);
  border: none;
  border-radius: var(--radius);
  cursor: pointer;
  transition: background-color var(--transition), transform 0.1s ease, box-shadow var(--transition);
}

.submit-btn:hover {
  background: var(--primary-hover);
  box-shadow: 0 4px 12px rgba(79, 70, 229, 0.35);
}

.submit-btn:active {
  transform: scale(0.98);
}

.submit-btn:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px var(--white), 0 0 0 5px var(--primary);
}

.submit-btn:disabled {
  background: #a5b4fc;
  cursor: not-allowed;
  box-shadow: none;
}

/* ===== Footer Text ===== */
.signup-text {
  margin-top: 1.5rem;
  text-align: center;
  font-size: 0.875rem;
  color: var(--text-muted);
}

/* ===== Responsive ===== */
@media (max-width: 480px) {
  .login-form {
    padding: 2rem 1.25rem;
