.cta-button:hover {
  background-color: var(--color-primary-hover);
  transform: translateY(-1px);
  box-shadow: 0 4px 12px rgba(79, 70, 229, 0.3);
}

.cta-button:active {
  transform: translateY(0);
  box-shadow: 0 1px 2px rgba(79, 70, 229, 0.2);
}

.cta-button:focus-visible {
  outline: 2px solid var(--color-primary);
  outline-offset: 3px;
}

/* ==========================================
   Mobile Menu Toggle (Hamburger)
   ========================================== */
.nav-toggle {
  display: none;
  position: relative;
  width: 44px;
  height: 44px;
  padding: 0;
  background: transparent;
  border: none;
  border-radius: var(--radius);
  cursor: pointer;
}

.nav-toggle:focus-visible {
  outline: 2px solid var(--color-primary);
}

.hamburger,
.hamburger::before,
.hamburger::after {
  position: absolute;
  left: 50%;
  width: 22px;
  height: 2px;
  background-color: var(--color-text);
  border-radius: 2px;
  transition: transform 0.3s ease, opacity 0.3s ease, top 0.3s ease;
}

.hamburger {
  top: 50%;
  transform: translate(-50%, -50%);
}

.hamburger::before,
.hamburger::after {
  content: "";
  transform: translateX(-50%);
}

.hamburger::before { top: -7px; }
.hamburger::after  { top: 7px; }

/* Hamburger → X animation */
.nav-toggle[aria-expanded="true"] .hamburger {
  background-color: transparent;
}

.nav-toggle[aria-expanded="true"] .hamburger::before {
  top: 0;
  transform: translateX(-50%) rotate(45deg);
}

.nav-toggle[aria-expanded="true"] .hamburger::after {
  top: 0;
  transform: translateX(-50%) rotate(-45deg);
}

/* ==========================================
   Responsive: Tablet & Mobile
   ========================================== */
@media (max-width: 860px) {
  .nav-toggle {
    display: block;
  }

  .main-nav {
    position: fixed;
    top: var(--header-height);
    left: 0;
    right: 0;
    bottom: 0;
    flex-direction: column;
    align-items: stretch;
    gap: 1.5rem;
    padding: 1.5rem var(--container-padding);
    background-color: var(--header-bg);
    border-top: 1px solid var(--header-border);
    overflow-y: auto;

    /* Hidden state */
    opacity: 0;
    visibility: hidden;
    transform: translateY(-10px);
    transition: opacity 0.25s ease, transform 0.25s ease, visibility 0.25s;
  }

  .main-nav.is-open {
    opacity: 1;
    visibility: visible;
    transform: translateY(0);
  }

  .nav-list {
    flex-direction: column;
    align-items: stretch;
    gap: 0.25rem;
  }

  .nav-link {
    padding: 0.875rem 1rem;
    font-size: 1.0625rem;
  }

  .nav-link.active::after,
  .nav-link[aria-current="page"]::after {
    left: 0;
    top: 50%;
    bottom: auto;
    width: 3px;
    height: 60%;
    border-radius: 2px;
    transform: translateY(-50%);
  }

  .nav-link.active,
  .nav-link[aria-current="page"] {
    background-color: var(--color-primary-light);
  }

  .cta-button {
    width: 100%;
    padding: 0.875rem 1.25rem;
    font-size: 1rem;
  }
}

/* Prevent body scroll when mobile menu is open */
body.nav-open {
  overflow: hidden;
}

/* ==========================================
   Accessibility: Reduced Motion
   ========================================== */
@media (prefers-reduced-motion: reduce) {
  .site-header *,
  .site-header *::before,
  .site-header *::after {
    transition-duration: 0.01ms !important;
  }
}
```

## JavaScript (for mobile toggle)

```javascript
const toggle = document.querySelector('.nav-toggle');
const nav = document.querySelector('.main-nav');

toggle.addEventListener('click', () => {
  const isOpen = toggle.getAttribute('aria-expanded') === 'true';
  toggle.setAttribute('aria-expanded', !isOpen);
  nav.classList.toggle('is-open');
  document.body.classList.toggle('nav-open');
});

// Close menu on Escape key
document.addEventListener('keydown', (e) => {
  if (e.key === 'Escape' && nav.classList.contains('is-open')) {
    toggle.setAttribute('aria-expanded', 'false');
    nav.classList.remove('is-open');
    document.body.classList.remove('nav-open');
    toggle.focus();
  }
});
```

## Key Features

| Feature | Description |
|---|---|
| **Sticky positioning** | Header stays visible while scrolling |
| **CSS variables** | Easy theming: change colors/sizes in one place |
| **Flexbox layout** | Logo left, nav + CTA right, vertically centered |
