    visibility: hidden;
    transform: translateY(-8px);
    transition: opacity var(--transition),
                transform var(--transition),
                visibility var(--transition);
  }

  .main-nav.open {
    opacity: 1;
    visibility: visible;
    transform: translateY(0);
