  letter-spacing: 0.06em;
}

.post-meta a {
  color: inherit;
  text-decoration: none;
  border-bottom: 1px solid transparent;
}

.post-meta a:hover {
  color: var(--color-accent);
  border-bottom-color: currentColor;
}

/* Dot separators between items */
.post-meta > * + *::before {
  content: "·";
  margin-right: 0.75rem;
  color: var(--color-rule);
  font-weight: 700;
}

/* ---------- Body text ---------- */

.post-body {
  font-size: clamp(1.0625rem, 0.5vw + 1rem, 1.25rem);
}

.post-body p {
  margin: 0 0 var(--space);
}

/* Drop cap on the first paragraph */
.post-body > p:first-of-type::first-letter {
  float: left;
  font-size: 3.6em;
  line-height: 0.85;
  font-weight: 700;
  padding: 0.08em 0.1em 0 0;
  color: var(--color-accent);
}

.post-body h2,
.post-body h3 {
  font-family: var(--font-sans);
  line-height: 1.25;
  margin: 2.5rem 0 1rem;
}

.post-body h2 { font-size: 1.75rem; }
.post-body h3 { font-size: 1.35rem; }

.post-body a {
  color: var(--color-accent);
  text-underline-offset: 0.2em;
}

.post-body a:hover {
  text-decoration-thickness: 2px;
}

.post-body img {
  max-width: 100%;
  height: auto;
  border-radius: 4px;
}

/* ---------- Pull quotes ---------- */

.pull-quote {
  position: relative;
  margin: 3rem 0;
  padding: 1.5rem 0 1.5rem 1.5rem;
  border-left: 4px solid var(--color-accent);
  font-size: clamp(1.4rem, 2vw + 1rem, 2rem);
  font-style: italic;
  line-height: 1.35;
  color: var(--color-text);
  text-wrap: balance;
}

.pull-quote p {
  margin: 0;
}

.pull-quote cite,
.pull-quote footer {
  display: block;
  margin-top: 0.75rem;
  font-family: var(--font-sans);
  font-size: 0.875rem;
  font-style: normal;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--color-muted);
}

.pull-quote cite::before {
  content: "— ";
}

/* On wide screens, let pull quotes break out of the text column */
@media (min-width: 1000px) {
  .pull-quote {
    margin-left: -4rem;
    margin-right: -4rem;
    padding-left: 2rem;
  }

  .pull-quote.float-right {
    float: right;
    width: 18rem;
    margin: 0.5rem -6rem 1.5rem 2rem;
    font-size: 1.4rem;
  }
}

/* ---------- Dark mode ---------- */

@media (prefers-color-scheme: dark) {
  :root {
    --color-text: #e8e6e3;
    --color-muted: #9a968f;
    --color-accent: #e8795f;
    --color-rule: #3a3835;
    --color-bg: #161513;
  }
}
```

