  letter-spacing: -0.02em;
}

.logo-img {
  width: 32px;
  height: 32px;
}

/* Navigation */
.main-nav {
  margin-left: auto;
}

.nav-list {
  display: flex;
  gap: 2rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.nav-link {
  position: relative;
  padding: 0.5rem 0;
  font-size: 0.95rem;
  font-weight: 500;
  color: var(--color-muted);
  text-decoration: none;
  transition: color 0.2s ease;
}

.nav-link::after {
  content: "";
  position: absolute;
  left: 0;
  bottom: 0;
  width: 100%;
  height: 2px;
  background: var(--color-primary);
  transform: scaleX(0);
  transform-origin: left;
  transition: transform 0.25s ease;
}

.nav-link:hover,
.nav-link.active {
  color: var(--color-text);
}

.nav-link:hover::after,
.nav-link.active::after {
  transform: scaleX(1);
}

/* Call-to-action button */
.btn-cta {
  display: inline-block;
  padding: 0.65rem 1.4rem;
  font-size: 0.95rem;
  font-weight: 600;
  color: #fff;
  background: var(--color-primary);
  border-radius: 8px;
  text-decoration: none;
  white-space: nowrap;
  transition: background 0.2s ease, transform 0.2s ease, box-shadow 0.2s ease;
}

.btn-cta:hover {
  background: var(--color-primary-dark);
  transform: translateY(-1px);
  box-shadow: 0 4px 12px rgba(79, 70, 229, 0.3);
}

/* Focus states for accessibility */
.logo:focus-visible,
.nav-link:focus-visible,
.btn-cta:focus-visible,
.nav-toggle:focus-visible {
  outline: 2px solid var(--color-primary);
  outline-offset: 3px;
  border-radius: 4px;
}

/* Mobile toggle (hidden on desktop) */
.nav-toggle {
  display: none;
  margin-left: auto;
  padding: 0.75rem 0.5rem;
  background: none;
  border: 0;
  cursor: pointer;
}

.nav-toggle .bar,
.nav-toggle .bar::before,
.nav-toggle .bar::after {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--color-text);
  border-radius: 2px;
  transition: transform 0.25s ease, background 0.25s ease;
}

.nav-toggle .bar {
  position: relative;
}

.nav-toggle .bar::before,
.nav-toggle .bar::after {
  content: "";
  position: absolute;
  left: 0;
}

.nav-toggle .bar::before { top: -7px; }
.nav-toggle .bar::after  { top: 7px; }

/* Animate into an "X" when open */
.nav-toggle[aria-expanded="true"] .bar { background: transparent; }
.nav-toggle[aria-expanded="true"] .bar::before { transform: translateY(7px) rotate(45deg); }
.nav-toggle[aria-expanded="true"] .bar::after  { transform: translateY(-7px) rotate(-45deg); }

/* Responsive */
@media (max-width: 768px) {
  .nav-toggle {
    display: block;
  }

  .main-nav {
    position: absolute;
    top: var(--header-height);
    left: 0;
    right: 0;
    margin: 0;
    background: var(--color-bg);
    border-bottom: 1px solid var(--color-border);
    max-height: 0;
    overflow: hidden;
    transition: max-height 0.3s ease;
  }

  .main-nav.open {
    max-height: 400px;
  }

  .nav-list {
    flex-direction: column;
    gap: 0;
    padding: 0.5rem 1.5rem 1rem;
  }

  .nav-link {
    display: block;
    padding: 0.85rem 0;
  }

  .nav-link::after {
    display: none;
  }

  .btn-cta {
    display: none; /* or move inside the mobile menu */
  }
}

@media (prefers-reduced-motion: reduce) {
  * {
    transition: none !important;
  }
}
```

## Optional JavaScript for the mobile menu

```js
const toggle = document.querySelector('.nav-toggle');
const nav = document.querySelector('.main-nav');

toggle.addEventListener('click', () => {
  const open = nav.classList.toggle('open');
  toggle.setAttribute('aria-expanded', open);
});
```

## Features

- **Sticky header** with a subtle blur effect
- **Flexbox layout**: logo on the left, nav and CTA on the right
- **Animated underline** on nav hover and for the active page
- **CSS variables** for easy theming
- **Accessible**: focus outlines, ARIA attributes, reduced-motion support
- **Responsive**: collapses to a hamburger menu under 768px

To keep the CTA visible on mobile, remove `display: none` from `.btn-cta` in the media query, or duplicate it inside the nav list.

