/* Structure: .site-header > .header-inner > .logo + .site-nav + .header-cta */
.site-header {
  background: #fff;
  border-bottom: 1px solid #e2e8f0;
  color: #0f172a;
}

.header-inner {
  display: flex;
  align-items: center;
  gap: 1rem 2rem;
  max-width: 72rem;
  margin-inline: auto;
  padding: 1rem 1.5rem;
}

.logo {
  color: inherit;
  font-size: 1.25rem;
  font-weight: 750;
  text-decoration: none;
}

.logo img {
  display: block;
  max-width: 10rem;
  height: auto;
}

.site-nav {
  margin-inline-start: auto;
}

.site-nav ul {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem 1.25rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.site-nav a {
  display: inline-block;
  padding-block: 0.5rem;
  color: #334155;
  text-decoration: none;
}

.site-nav a:hover,
.site-nav a[aria-current="page"] {
  color: #1d4ed8;
  text-decoration: underline;
  text-underline-offset: 0.25em;
}

.header-cta {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.65rem 1rem;
  border: 0;
  border-radius: 0.5rem;
  background: #1d4ed8;
  color: #fff;
  font: inherit;
  font-weight: 600;
  text-decoration: none;
  cursor: pointer;
}

.header-cta:hover {
  background: #1e40af;
}

