  --header-bg: #ffffff;
  --text-color: #1f2937;
  --text-muted: #4b5563;
  --primary-color: #2563eb;
  --primary-hover: #1d4ed8;
  --border-color: #e5e7eb;
}

/* Header Container */
.site-header {
  background-color: var(--header-bg);
  border-bottom: 1px solid var(--border-color);
  position: sticky;
  top: 0;
  z-index: 1000;
}

.header-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 1rem 1.5rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 2rem;
}

/* Logo */
.logo {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--text-color);
  text-decoration: none;
  letter-spacing: -0.025em;
}

/* Navigation Links */
.nav-list {
  display: flex;
  list-style: none;
  margin: 0;
  padding: 0;
  gap: 2rem;
}

.nav-link {
  color: var(--text-muted);
  text-decoration: none;
  font-size: 0.95rem;
  font-weight: 500;
  transition: color 0.2s ease;
}

.nav-link:hover {
  color: var(--primary-color);
}

/* Call-to-Action Button */
.cta-button {
  background-color: var(--primary-color);
  color: #ffffff;
  text-decoration: none;
  padding: 0.6rem 1.25rem;
  border-radius: 6px;
  font-size: 0.95rem;
  font-weight: 600;
  transition: background-color 0.2s ease;
  white-space: nowrap;
}

.cta-button:hover {
  background-color: var(--primary-hover);
}

/* Basic Mobile Responsiveness */
@media (max-width: 768px) {
  .header-container {
    flex-wrap: wrap;
    gap: 1rem;
  }

  .main-nav {
    order: 3;
    width: 100%;
    border-top: 1px solid var(--border-color);
