/* ---------------------------------------
   Variables
--------------------------------------- */
:root {
  --text-color: #1f2933;
  --text-muted: #616e7c;
  --accent-color: #c0392b;
  --divider-color: #e4e7eb;
  --content-width: 42rem;
  --measure: 68ch;
}

/* ---------------------------------------
   Post Container
--------------------------------------- */
.post {
  max-width: var(--content-width);
  margin: 0 auto;
  padding: 2rem 1.5rem 4rem;
  font-family: Georgia, "Times New Roman", serif;
  color: var(--text-color);
  line-height: 1.7;
}

/* ---------------------------------------
   Title
--------------------------------------- */
.post-title {
  font-size: clamp(2rem, 5vw, 3rem);
  font-weight: 700;
  line-height: 1.15;
  letter-spacing: -0.02em;
  margin: 0 0 1rem;
  color: var(--text-color);
}

/* ---------------------------------------
   Metadata Line
--------------------------------------- */
.post-meta {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.5rem;
  padding-bottom: 1.5rem;
