  font-size: clamp(2rem, 1.4rem + 3vw, 3.25rem);
  font-weight: 700;
  line-height: 1.1;
  letter-spacing: -0.02em;
  text-wrap: balance;
}

/* ---------- Metadata line ---------- */

.post__meta {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.5rem 0.75rem;
  margin: 0 0 2.5rem;
  padding-bottom: 1.25rem;
  border-bottom: 1px solid var(--rule);

  font-family: var(--font-ui);
  font-size: 0.8125rem;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--ink-muted);
}

/* middot separators between items */
.post__meta > * + *::before {
  content: "·";
  margin-inline-end: 0.75rem;
  opacity: 0.5;
}

.post__meta a {
  color: inherit;
  text-decoration: none;
}

.post__meta a:hover {
  color: var(--accent);
}

/* ---------- Body text ---------- */

.post__body {
  display: flow-root; /* contains floated pull quotes */
}

.post__body > :first-child {
  margin-top: 0;
}

.post__body > p {
  margin: 0 0 1.5em;
  text-wrap: pretty;
}

.post__body > p:last-child {
  margin-bottom: 0;
}

.post__body a {
  color: inherit;
  text-decoration-color: var(--accent);
  text-decoration-thickness: 1px;
  text-underline-offset: 0.15em;
}

.post__body a:hover {
  color: var(--accent);
}

/* ---------- Pull quotes ---------- */

.pullquote {
  margin: 0;
  font-family: var(--font-ui);
  font-size: clamp(1.25rem, 1.1rem + 0.8vw, 1.6rem);
  font-weight: 600;
  line-height: 1.3;
  letter-spacing: -0.01em;
  color: var(--accent);
  text-wrap: balance;
}

/* Floated variants */
.pullquote--right,
.pullquote--left {
  width: min(16rem, 45%);
  margin-block: 0.35em 1em;
}

.pullquote--right {
  float: right;
  margin-inline-start: 2rem;
  padding-inline-start: 1.25rem;
  border-inline-start: 3px solid var(--accent);
}

.pullquote--left {
  float: left;
  margin-inline-end: 2rem;
  padding-inline-end: 1.25rem;
  border-inline-end: 3px solid var(--accent);
}

/* Centered, full-width variant */
.pullquote--center {
  max-width: 30ch;
  margin: 2.5rem auto;
  padding-block: 1.25rem;
  border-block: 1px solid var(--rule);
  text-align: center;
  font-size: clamp(1.4rem, 1.2rem + 1.2vw, 2rem);
}

/* ---------- Narrow screens: unfloat ---------- */

@media (max-width: 40rem) {
  .pullquote--left,
  .pullquote--right {
    float: none;
    width: auto;
    margin-block: 1.75rem;
    margin-inline: 0;
    padding-inline: 1rem 0;
    border-inline: 0;
    border-inline-start: 3px solid var(--accent);
  }
}
