/* --------------------------------------------------------------------------
   Title
   -------------------------------------------------------------------------- */

.post__title {
  margin: 0 0 0.75em;
  font-family: var(--font-sans);
  font-size: clamp(2.125rem, 1.35rem + 3.2vw, 3.5rem);
  font-weight: 700;
  line-height: 1.08;
  letter-spacing: -0.025em;
  text-wrap: balance;
}

/* --------------------------------------------------------------------------
   Metadata line
   -------------------------------------------------------------------------- */

.post__meta {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 0.35rem 0.75rem;
  margin: 0 0 clamp(2rem, 5vw, 3.5rem);
  padding-bottom: 1.5rem;
  border-bottom: 1px solid var(--rule);

  font-family: var(--font-sans);
  font-size: 0.8125rem;
  line-height: 1.4;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--ink-muted);
}

/* Interpunct between each metadata item */
.post__meta > * + *::before {
  content: "·";
  margin-right: 0.75rem;
  color: var(--ink-faint);
}

.post__meta a {
  color: inherit;
  text-decoration: none;
  border-bottom: 1px solid var(--rule);
  transition: border-color 0.15s ease, color 0.15s ease;
}

.post__meta a:hover {
  color: var(--accent);
  border-bottom-color: currentColor;
}

/* --------------------------------------------------------------------------
   Body text
   -------------------------------------------------------------------------- */

.post__body {
  overflow-wrap: break-word;
}

/* Lobotomised-owl spacing: every element after the first gets a top margin */
.post__body > * + * {
  margin-block-start: var(--flow);
}

.post__body p {
  margin: 0;
  text-wrap: pretty;
}

.post__body h2 {
  margin-block-start: 2.25em;
  font-family: var(--font-sans);
  font-size: clamp(1.375rem, 1.15rem + 0.9vw, 1.75rem);
  line-height: 1.25;
  letter-spacing: -0.015em;
  text-wrap: balance;
}

/* Tighter gap directly beneath a heading */
.post__body > h2 + * {
  margin-block-start: 0.6em;
}

.post__body a {
  color: inherit;
  text-decoration-line: underline;
  text-decoration-color: var(--accent);
  text-decoration-thickness: 1px;
  text-underline-offset: 0.2em;
  transition: color 0.15s ease;
}

.post__body a:hover {
  color: var(--accent);
}

.post__body img {
  display: block;
  width: 100%;
  height: auto;
  border-radius: 2px;
}

.post__body hr {
  margin-block: 3em;
  border: 0;
  border-top: 1px solid var(--rule);
}

/* --------------------------------------------------------------------------
   Pull quotes
   -------------------------------------------------------------------------- */

.pullquote {
  margin-block: 2.5em;
  padding-left: 1.25rem;
  border-left: 3px solid var(--accent);

  font-family: var(--font-sans);
  font-size: clamp(1.25rem, 1.05rem + 0.85vw, 1.625rem);
  font-weight: 600;
  line-height: 1.35;
  letter-spacing: -0.015em;
  text-wrap: balance;
}

.pullquote p {
  margin: 0;
}

.pullquote cite {
  display: block;
  margin-top: 0.75em;
  font-size: 0.8125rem;
  font-weight: 500;
  font-style: normal;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--ink-muted);
}

/* Floated variant — sits beside the text on wider viewports */
@media (min-width: 62rem) {
  .pullquote--float {
    float: right;
    width: 14rem;
    margin: 0.4rem 0 1.5rem 2.5rem;
    padding-left: 1rem;
    font-size: 1.125rem;
    line-height: 1.4;
  }
}

/* Keep the float from escaping the article */
.post__body::after {
  content: "";
  display: block;
  clear: both;
}

/* --------------------------------------------------------------------------
   Niceties
   -------------------------------------------------------------------------- */

::selection {
  background: var(--accent);
  color: var(--bg);
}

.post__body a:focus-visible,
.post__meta a:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
  border-radius: 2px;
}

@media (prefers-reduced-motion: reduce) {
  * {
    transition-duration: 0.01ms !important;
  }
}
