/* ==========================================================================
   Blog post layout
   ========================================================================== */

:root {
  --post-font-body: "Iowan Old Style", "Palatino Linotype", Palatino, Georgia, serif;
  --post-font-ui: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --post-font-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;

  --post-text: #1c1c1c;
  --post-text-muted: #6a6a6a;
  --post-accent: #a8442a;
  --post-rule: #e4e2df;
  --post-bg: #fdfdfc;

  --post-measure: 68ch;   /* ~65–75 characters per line */
  --post-flow: 1.5rem;    /* vertical rhythm unit */
  --post-radius: 4px;
}

@media (prefers-color-scheme: dark) {
  :root {
    --post-text: #e8e6e3;
    --post-text-muted: #9a9691;
    --post-accent: #e0805f;
    --post-rule: #33312e;
    --post-bg: #16151a;
  }
}

/* --- Shell ---------------------------------------------------------------- */

.post {
  box-sizing: border-box;
  max-width: var(--post-measure);
  margin-inline: auto;
  padding: clamp(2rem, 6vw, 5rem) clamp(1.25rem, 5vw, 2rem) 4rem;

  background: var(--post-bg);
  color: var(--post-text);
  font-family: var(--post-font-body);
  font-size: clamp(1.0625rem, 1rem + 0.35vw, 1.1875rem);
  line-height: 1.65;
  font-kerning: normal;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
}

.post *,
.post *::before,
.post *::after {
  box-sizing: inherit;
}

/* --- Header --------------------------------------------------------------- */

.post__header {
  margin-bottom: clamp(2rem, 5vw, 3rem);
  padding-bottom: clamp(1.5rem, 4vw, 2rem);
  border-bottom: 1px solid var(--post-rule);
}

.post__title {
  margin: 0;
  font-family: var(--post-font-ui);
  font-size: clamp(2rem, 1.35rem + 3.2vw, 3.25rem);
  font-weight: 700;
  line-height: 1.08;
  letter-spacing: -0.022em;
  text-wrap: balance;          /* progressive enhancement */
}

/* --- Metadata line -------------------------------------------------------- */

.post__meta {
  margin: 1rem 0 0;
  font-family: var(--post-font-ui);
  font-size: 0.8125rem;
  line-height: 1.6;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--post-text-muted);
}

.post__meta-item {
  white-space: nowrap;
}

/* Dot separators between items */
.post__meta-item:not(:last-child)::after {
  content: "";
  display: inline-block;
  inline-size: 3px;
  block-size: 3px;
  margin-inline: 0.7em;
  border-radius: 50%;
  background: currentColor;
  vertical-align: 0.15em;
  opacity: 0.55;
}

.post__meta-author {
  color: var(--post-text);
  font-weight: 600;
}

/* --- Body flow ------------------------------------------------------------ */

.post__body {
  display: flow-root;   /* contains floated pull quotes */
}

.post__body > * {
  margin-block: 0;
}

.post__body > * + * {
  margin-block-start: var(--post-flow);
}

.post__body > h2 {
  margin-block-start: 2.25rem;
  font-family: var(--post-font-ui);
  font-size: 1.5em;
  line-height: 1.25;
  letter-spacing: -0.01em;
  text-wrap: balance;
}

.post__body > h3 {
  margin-block-start: 2rem;
  font-family: var(--post-font-ui);
  font-size: 1.15em;
  line-height: 1.3;
}

/* Links */
.post__body a {
  color: inherit;
  text-decoration-line: underline;
  text-decoration-thickness: 1px;
  text-underline-offset: 0.15em;
  text-decoration-color: color-mix(in srgb, currentColor 35%, transparent);
  transition: text-decoration-color 150ms ease;
}

