/* ==========================================================================
   Pull quotes
   ========================================================================== */

/* Base: centered, rule-bound, breaks the column */
.pullquote {
  margin-block: 2.5rem;
  padding-block: 1.75rem;
  border-block: 1px solid var(--post-rule);
  font-size: 1.3em;
  line-height: 1.35;
  font-style: italic;
  text-align: center;
  text-wrap: balance;
  color: var(--post-text);
}

.pullquote p {
  margin: 0;
}

.pullquote cite,
.pullquote__attribution {
  display: block;
  margin-block-start: 0.75rem;
  font-family: var(--post-font-ui);
  font-size: 0.72em;
  font-style: normal;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--post-text-muted);
}

/* Floated variants — only float once there's room for the text to wrap */
@media (min-width: 48rem) {
  .pullquote--float-right,
  .pullquote--float-left {
    inline-size: min(15rem, 42%);
    margin-block: 0.35rem 1.25rem;
    padding-block: 0;
    border-block: 0;
    border-block-start: 3px solid var(--post-accent);
    font-size: 1.15em;
    line-height: 1.3;
    text-align: start;
    text-wrap: pretty;
  }

  .pullquote--float-right {
    float: right;
    margin-inline: 2rem 0;
  }

  .pullquote--float-left {
    float: left;
    margin-inline: 0 2rem;
  }
}

/* --- Accessibility & print ------------------------------------------------ */

.post :focus-visible {
  outline: 2px solid var(--post-accent);
  outline-offset: 3px;
  border-radius: 2px;
}

.post ::selection {
  background: color-mix(in srgb, var(--post-accent) 25%, transparent);
}

@media (prefers-reduced-motion: reduce) {
  .post__body a {
    transition: none;
  }
}

@media print {
  .post {
    max-width: none;
    padding: 0;
    background: none;
    color: #000;
    font-size: 11pt;
  }

  .pullquote--float-right,
  .pullquote--float-left {
    float: none;
    inline-size: auto;
    margin-inline: 0;
  }

  .post__body a {
    text-decoration: none;
  }
}
