/* ==========================================================================
   1. Tokens
   ========================================================================== */
:root {
  --font-body: "Iowan Old Style", "Palatino Linotype", Georgia, serif;
  --font-head: "Inter", "Helvetica Neue", system-ui, -apple-system, sans-serif;

  --color-text:        #1c1c1c;
  --color-text-muted:  #6d6d6d;
  --color-accent:      #a8432c;
  --color-rule:        #e4e2de;
  --color-bg:          #ffffff;

  --measure: 42rem;          /* ~66–70 characters at 17px */
  --leading: 1.7;
  --flow: 1.5rem;            /* vertical rhythm between paragraphs */
}

@media (prefers-color-scheme: dark) {
  :root {
    --color-text:       #eae7e2;
    --color-text-muted: #9a958e;
    --color-accent:     #e08a6f;
    --color-rule:       #33312e;
    --color-bg:         #171614;
  }
}

/* ==========================================================================
   2. Article shell
   ========================================================================== */
.post {
  max-width: var(--measure);
  margin: 0 auto;
  padding: clamp(2rem, 6vw, 5rem) 1.25rem;
  background: var(--color-bg);
  color: var(--color-text);
  font-family: var(--font-body);
}

/* ==========================================================================
   3. Title
   ========================================================================== */
.post-title {
  margin: 0 0 0.75rem;
  font-family: var(--font-head);
  font-size: clamp(2rem, 1.4rem + 3.2vw, 3.25rem);
  font-weight: 800;
  line-height: 1.08;
  letter-spacing: -0.025em;
  text-wrap: balance;           /* avoids a lonely last word */
}

/* ==========================================================================
   4. Metadata line
   ========================================================================== */
.post-meta {
  display: flex;
  flex-wrap: wrap;
  margin: 0 0 2.5rem;
  padding: 0;
  list-style: none;
  font-family: var(--font-head);
  font-size: 0.8125rem;
  line-height: 1.5;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--color-text-muted);
}

/* Separator dots between items */
.post-meta li + li::before {
  content: "·";
  margin: 0 0.6em;
  opacity: 0.55;
}

.post-meta a {
  color: inherit;
  text-decoration: none;
  border-bottom: 1px solid var(--color-rule);
  transition: border-color 120ms ease, color 120ms ease;
}
.post-meta a:hover {
  color: var(--color-accent);
  border-bottom-color: currentColor;
}

/* ==========================================================================
   5. Body text
   ========================================================================== */
.post-body {
  font-size: 1.0625rem;         /* 17px */
  line-height: var(--leading);
  display: flow-root;           /* contains floated pull quotes */
}

.post-body p {
  margin: 0 0 var(--flow);
  text-wrap: pretty;
}

/* Opening paragraph, set slightly larger */
.post-body .lead {
  font-size: 1.1875rem;
  line-height: 1.6;
  color: var(--color-text);
}

.post-body a {
  color: var(--color-accent);
  text-decoration: underline;
  text-decoration-thickness: 1px;
  text-underline-offset: 0.15em;
  text-decoration-color: color-mix(in srgb, currentColor 40%, transparent);
  transition: text-decoration-color 120ms ease;
}
.post-body a:hover {
  text-decoration-color: currentColor;
}

.post-body h2,
.post-body h3 {
  margin: 2.5rem 0 1rem;
  font-family: var(--font-head);
  font-weight: 700;
  line-height: 1.25;
  letter-spacing: -0.015em;
  text-wrap: balance;
}
.post-body h2 { font-size: 1.5rem; }
.post-body h3 { font-size: 1.1875rem; }

.post-body ul,
.post-body ol {
  margin: 0 0 var(--flow);
  padding-left: 1.25em;
}
.post-body li { margin-bottom: 0.4em; }
.post-body li::marker { color: var(--color-text-muted); }

.post-body img {
  display: block;
  max-width: 100%;
  height: auto;
  margin: 2rem 0;
  border-radius: 4px;
}

.post-body hr {
  margin: 3rem auto;
  width: 6rem;
  border: 0;
  border-top: 1px solid var(--color-rule);
}

/* Regular blockquote — deliberately different from a pull quote */
.post-body blockquote {
  margin: 2rem 0;
  padding-left: 1.25rem;
  border-left: 2px solid var(--color-rule);
  font-style: italic;
  color: var(--color-text-muted);
}
.post-body blockquote p:last-child { margin-bottom: 0; }

/* ==========================================================================
   6. Pull quotes
   ========================================================================== */
.pullquote {
  margin: 2.25rem 0;
  padding: 0;
  border: 0;
  font-family: var(--font-head);
  font-size: clamp(1.25rem, 1rem + 1.4vw, 1.625rem);
  font-weight: 600;
  line-height: 1.3;
  letter-spacing: -0.02em;
  text-wrap: balance;
  color: var(--color-text);
}

.pullquote p { margin: 0; }

.pullquote cite {
  display: block;
  margin-top: 0.75rem;
  font-size: 0.75rem;
  font-style: normal;
  font-weight: 500;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--color-text-muted);
}

/* --- 6a. Inline variant: centered, rules above and below --------------- */
.pullquote--inline {
  padding: 1.75rem 0;
  border-top: 2px solid var(--color-text);
  border-bottom: 2px solid var(--color-text);
  text-align: center;
}

/* --- 6b. Floated variant: hangs to the side on wide screens ------------ */
.pullquote--right {
  float: right;
  width: 15rem;
  margin: 0.4rem 0 1.25rem 2rem;
  text-align: left;
}

.pullquote--left {
  float: left;
  width: 15rem;
  margin: 0.4rem 2rem 1.25rem 0;
  text-align: left;
}

/* A hairline rule makes the float read as a separate object */
.pullquote--right,
.pullquote--left {
  padding-top: 1rem;
  border-top: 2px solid var(--color-accent);
}

/* Below the breakpoint, floats collapse into full-width inline quotes */
@media (max-width: 44rem) {
  .pullquote--right,
  .pullquote--left {
    float: none;
    width: auto;
    margin: 2.25rem 0;
    padding: 1.5rem 0;
    border-top: 2px solid var(--color-text);
    border-bottom: 2px solid var(--color-text);
    text-align: center;
  }
}

/* ==========================================================================
   7. Optional: pull quote hanging into the page margin on very wide screens
   ========================================================================== */
@media (min-width: 78rem) {
  .pullquote--hang {
    float: right;
    width: 18rem;
    margin-right: -22%;       /* pushes into the gutter */
    margin-left: 2.5rem;
  }
}
