          <path d="M9 22 16 9l7 13" fill="none" stroke="#fff"
                stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/>
        </svg>
        <span class="logo__text">Acme</span>
      </a>

      <nav class="nav" id="site-nav" aria-label="Main">
        <ul class="nav__list">
          <li><a class="nav__link" href="#" aria-current="page">Product</a></li>
          <li><a class="nav__link" href="#">Solutions</a></li>
          <li><a class="nav__link" href="#">Pricing</a></li>
          <li><a class="nav__link" href="#">Docs</a></li>
        </ul>
      </nav>

      <div class="site-header__actions">
        <a class="btn btn--ghost" href="#">Sign in</a>
        <a class="btn btn--primary" href="#">Get started</a>
      </div>

      <button class="nav-toggle" type="button"
              aria-expanded="false" aria-controls="site-nav"
              aria-label="Toggle navigation">
        <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false">
          <path d="M4 7h16M4 12h16M4 17h16" fill="none" stroke="currentColor"
                stroke-width="2" stroke-linecap="round"/>
        </svg>
      </button>

