  --shadow-sm: 0 1px 2px rgb(15 23 42 / 0.06);
  --shadow-md: 0 8px 24px -8px rgb(15 23 42 / 0.18);

  --ease: cubic-bezier(0.4, 0, 0.2, 1);
}

/* ============================================================
   Base
   ============================================================ */
*,
*::before,
*::after { box-sizing: border-box; }

body {
  margin: 0;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  color: var(--color-text);
  background: #f8fafc;
  -webkit-font-smoothing: antialiased;
}

/* ============================================================
   Header shell
   ============================================================ */
.site-header {
  position: sticky;
  top: 0;
  z-index: 50;
  background: color-mix(in srgb, var(--color-bg) 85%, transparent);
  border-bottom: 1px solid var(--color-border);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
}

.header-inner {
  position: relative;                /* anchor for the mobile nav panel */
  display: flex;
  align-items: center;
  gap: 1.5rem;
  max-width: 1200px;
  height: var(--header-height);
  margin-inline: auto;
  padding-inline: clamp(1rem, 4vw, 2rem);
}

/* ============================================================
   Logo
   ============================================================ */
.logo {
  display: inline-flex;
  align-items: center;
  gap: 0.625rem;
  margin-right: auto;                /* pushes nav + CTA to the right */
  color: var(--color-brand);
  text-decoration: none;
  font-weight: 700;
  font-size: 1.125rem;
  letter-spacing: -0.02em;
  border-radius: var(--radius-sm);
}

.logo-mark {
  width: 2rem;
  height: 2rem;
  flex-shrink: 0;
}

.logo-text {
  color: var(--color-text);
}

/* ============================================================
   Navigation
   ============================================================ */
.nav-list {
  display: flex;
  align-items: center;
  gap: 0.25rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.nav-link {
  position: relative;
  display: block;
  padding: 0.5rem 0.875rem;
  color: var(--color-muted);
  font-size: 0.9375rem;
  font-weight: 500;
  text-decoration: none;
  border-radius: var(--radius-sm);
  transition: color 0.18s var(--ease), background-color 0.18s var(--ease);
}

.nav-link:hover {
  color: var(--color-text);
  background: #f1f5f9;
}

/* Animated underline */
.nav-link::after {
  content: "";
  position: absolute;
  left: 0.875rem;
  right: 0.875rem;
  bottom: 0.25rem;
  height: 2px;
  background: var(--color-brand);
  border-radius: 2px;
  transform: scaleX(0);
  transform-origin: left center;
  transition: transform 0.22s var(--ease);
}

.nav-link:hover::after,
.nav-link:focus-visible::after {
  transform: scaleX(1);
}

/* ============================================================
   Buttons
   ============================================================ */
.header-actions {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.5625rem 1.125rem;
  font-size: 0.9375rem;
  font-weight: 600;
  line-height: 1.2;
  white-space: nowrap;
  text-decoration: none;
  border: 1px solid transparent;
  border-radius: var(--radius-md);
  cursor: pointer;
  transition:
    background-color 0.18s var(--ease),
    border-color     0.18s var(--ease),
    color            0.18s var(--ease),
    box-shadow       0.18s var(--ease),
    transform        0.12s var(--ease);
}

.btn:active { transform: translateY(1px); }

.btn-primary {
  background: var(--color-brand);
  color: #fff;
  box-shadow: var(--shadow-sm);
}

.btn-primary:hover {
  background: var(--color-brand-dk);
  box-shadow: var(--shadow-md);
}

.btn-ghost {
  color: var(--color-text);
  background: transparent;
  border-color: var(--color-border);
}

.btn-ghost:hover {
  background: #f1f5f9;
  border-color: #cbd5e1;
}

/* ============================================================
   Focus states (keyboard accessibility)
   ============================================================ */
.logo:focus-visible,
.nav-link:focus-visible,
.btn:focus-visible,
.nav-toggle-label:focus-visible {
  outline: 2px solid var(--color-brand);
  outline-offset: 2px;
}

/* ============================================================
   Mobile toggle button
   ============================================================ */
.nav-toggle-label {
  display: none;                     /* hidden on desktop */
  flex-direction: column;
  justify-content: center;
  gap: 5px;
  width: 2.5rem;
  height: 2.5rem;
  padding: 0.5rem;
  border-radius: var(--radius-sm);
  cursor: pointer;
}

.nav-toggle-label .bar {
  display: block;
  width: 100%;
  height: 2px;
  background: var(--color-text);
  border-radius: 2px;
  transition: transform 0.22s var(--ease), opacity 0.18s var(--ease);
}

/* Turn the hamburger into an X when open */
.nav-toggle:checked ~ .nav-toggle-label .bar:nth-child(1) {
  transform: translateY(7px) rotate(45deg);
}
.nav-toggle:checked ~ .nav-toggle-label .bar:nth-child(2) {
  opacity: 0;
}
.nav-toggle:checked ~ .nav-toggle-label .bar:nth-child(3) {
  transform: translateY(-7px) rotate(-45deg);
}

/* ============================================================
   Responsive — tablet & below
   ============================================================ */
@media (max-width: 860px) {
  .nav-toggle-label { display: flex; }

  .nav {
    position: absolute;
    top: var(--header-height);
    left: 0;
    right: 0;
    display: none;
    padding: 0.75rem clamp(1rem, 4vw, 2rem) 1.25rem;
    background: var(--color-surface);
    border-bottom: 1px solid var(--color-border);
    box-shadow: var(--shadow-md);
  }

  /* Open state */
  .nav-toggle:checked ~ .nav {
    display: block;
    animation: nav-in 0.2s var(--ease);
  }

  .nav-list {
    flex-direction: column;
    align-items: stretch;
    gap: 0.125rem;
  }

  .nav-link {
    padding: 0.75rem 0.875rem;
    font-size: 1rem;
  }

  .nav-link::after { display: none; }
}

@keyframes nav-in {
  from { opacity: 0; transform: translateY(-6px); }
  to   { opacity: 1; transform: translateY(0); }
}

/* ============================================================
   Small phones
   ============================================================ */
@media (max-width: 480px) {
  .btn-ghost { display: none; }      /* keep only the primary CTA */
  .btn { padding: 0.5rem 0.875rem; font-size: 0.875rem; }
  .logo-text { font-size: 1rem; }
}

/* ============================================================
   Reduced motion
   ============================================================ */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }
}
```
### Header Layout & Responsive Behavior

The header keeps the logo left-aligned, navigation centered-right, and the CTA button on the far right. On smaller screens, the nav links collapse into a dropdown menu triggered by a hamburger icon, while the primary CTA stays visible.

- **Logo area** – an SVG mark paired with the site name, using a flexible layout that pushes the rest of the header content to the right.
- **Navigation links** – a horizontal list with a subtle animated underline on hover, plus a light background highlight for feedback.
- **Call-to-action buttons** – a ghost-style “Log in” link and a solid blue “Get started” button, both with hover and active states.
- **Mobile menu** – the checkbox-based toggle turns into an X icon when opened, and the nav panel slides in below the header without JavaScript.
- **Accessibility touches** – visible focus outlines, reduced-motion support, and proper ARIA labels on the logo and menu toggle.
---

**Optimization Tip:** You can replace the “Acme” logo text and the placeholder `#` links with your own brand name and URLs. The primary blue color is controlled by `--color-brand` in the `:root` block, so you can adjust the whole theme from there.

