  color: var(--muted-color);
}

.post__meta a {
  color: inherit;
  text-decoration: none;
  font-weight: 600;
}

.post__meta a:hover {
  color: var(--accent-color);
  text-decoration: underline;
}

/* Separator dot between meta items */
.post__meta > * + *::before {
  content: "·";
  margin-right: 0.5rem;
  color: var(--border-color);
}

/* ---------- Body text ---------- */

.post__body > * + * {
  margin-top: 1.25em;
}

.post__body p {
  margin: 0;
}

.post__body h2,
.post__body h3,
.post__body h4 {
  font-family: var(--font-display);
  line-height: 1.3;
  margin-top: 2em;
  margin-bottom: 0.6em;
  letter-spacing: -0.01em;
}

.post__body h2 { font-size: 1.5rem; }
.post__body h3 { font-size: 1.25rem; }

.post__body a {
  color: var(--accent-color);
  text-decoration-thickness: 1px;
  text-underline-offset: 2px;
}

.post__body a:hover {
  text-decoration-thickness: 2px;
}

.post__body img,
.post__body video {
  max-width: 100%;
  height: auto;
  border-radius: 6px;
  display: block;
}

.post__body ul,
.post__body ol {
  padding-left: 1.5rem;
}

.post__body li + li {
  margin-top: 0.4rem;
}

.post__body code {
  font-family: ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, monospace;
  font-size: 0.875em;
  background: rgba(175, 184, 193, 0.2);
  padding: 0.15em 0.35em;
  border-radius: 4px;
}

.post__body pre {
  background: #f6f8fa;
  border: 1px solid var(--border-color);
  border-radius: 6px;
  padding: 1rem;
  overflow-x: auto;
  font-size: 0.875rem;
  line-height: 1.5;
}

.post__body pre code {
  background: none;
  padding: 0;
  font-size: inherit;
}

.post__body hr {
  border: 0;
  border-top: 1px solid var(--border-color);
  margin: 2.5rem 0;
}

/* ---------- Pull quotes ---------- */

.pullquote {
  margin: 2.5rem 0;
  padding: 0.25rem 0 0.25rem 1.5rem;
  border-left: 4px solid var(--accent-color);
  font-family: var(--font-display);
  font-size: 1.375rem;
  line-height: 1.45;
  font-style: italic;
  font-weight: 600;
  color: var(--quote-color);
  text-wrap: pretty;
}

.pullquote p {
  margin: 0;
}

/* Attribution under the quote */
.pullquote cite {
  display: block;
  margin-top: 0.75rem;
  font-family: var(--font-body);
  font-size: 0.875rem;
  font-style: normal;
  font-weight: 500;
  letter-spacing: 0.02em;
  text-transform: uppercase;
  color: var(--muted-color);
}

.pullquote cite::before {
  content: "— ";
}

/* Large centered pull quote (optional variant) */
.pullquote--center {
  border-left: 0;
  border-top: 3px solid var(--accent-color);
  border-bottom: 3px solid var(--accent-color);
  padding: 1.5rem 0;
  text-align: center;
  font-size: 1.5rem;
}

/* ---------- Footer / tags ---------- */

.post__footer {
  margin-top: 3rem;
  padding-top: 1.5rem;
  border-top: 1px solid var(--border-color);
  font-size: 0.9375rem;
  color: var(--muted-color);
}

.post__tags {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  list-style: none;
  padding: 0;
  margin: 0;
}

.post__tags a {
  display: inline-block;
  padding: 0.2rem 0.7rem;
  border: 1px solid var(--border-color);
  border-radius: 999px;
  font-size: 0.8125rem;
  text-decoration: none;
  color: var(--muted-color);
}

.post__tags a:hover {
  border-color: var(--accent-color);
  color: var(--accent-color);
}

/* ---------- Responsive ---------- */

@media (max-width: 40rem) {
  .post {
    padding: 2rem 1rem 3rem;
    font-size: 1rem;
  }

  .pullquote {
    font-size: 1.2rem;
    padding-left: 1rem;
  }
}

/* ---------- Dark mode ---------- */

@media (prefers-color-scheme: dark) {
  :root {
    --text-color: #e6edf3;
    --muted-color: #9198a1;
    --accent-color: #4493f8;
    --quote-color: #b1bac4;
    --bg-color: #0d1117;
    --border-color: #30363d;
  }

  .post__body pre {
    background: #161b22;
  }

  .post__body code {
    background: rgba(110, 118, 129, 0.4);
  }
}
