.post-meta__author:hover {
  text-decoration: underline;
}

.post-meta__separator {
  color: #afb8c1;
}

/* ---------- Body text ---------- */

.post-body p {
  margin: 0 0 1.25rem;
}

.post-body h2 {
  margin: 2.5rem 0 1rem;
  font-size: 1.5rem;
  line-height: 1.3;
  font-weight: 650;
  letter-spacing: -0.01em;
}

.post-body h3 {
  margin: 2rem 0 0.75rem;
  font-size: 1.2rem;
  font-weight: 650;
}

.post-body a {
  color: var(--accent-color);
  text-decoration: underline;
  text-underline-offset: 2px;
}

.post-body a:hover {
  text-decoration-thickness: 2px;
}

.post-body ul,
.post-body ol {
  margin: 0 0 1.25rem;
  padding-left: 1.5rem;
}

.post-body li {
  margin-bottom: 0.4rem;
}

.post-body img {
  max-width: 100%;
  height: auto;
  border-radius: 6px;
  display: block;
  margin: 2rem 0;
}

.post-body code {
  font-family: ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, monospace;
  font-size: 0.875em;
  background: rgba(175, 184, 193, 0.2);
