  text-transform: uppercase;
  color: var(--muted-color);
}

/* Optional: centered pull quote variant */
.pull-quote--center {
  border-left: none;
  border-top: 2px solid var(--quote-border);
  border-bottom: 2px solid var(--quote-border);
  border-radius: 0;
