.post__meta a:hover {
  color: var(--color-text);
  border-bottom-color: var(--color-rule);
}

/* Separator dots between items */
.post__meta > * + *::before {
  content: "·";
  margin-right: 0.5rem;
  color: var(--color-rule);
}

/* Hide the dot before the first item after a flex gap */
.post__meta > :first-child + *::before {
  content: none;
}

/* Optional avatar */
.post__avatar {
  width: 2rem;
  height: 2rem;
  border-radius: 50%;
  object-fit: cover;
  margin-right: 0.25rem;
}

/* --------------------------------------------
   Body text
   -------------------------------------------- */
.post__body > * {
  margin-block: 0 var(--space);
}

.post__body p {
  text-wrap: pretty;
}

/* First paragraph slightly larger (drop cap optional) */
.post__body > p:first-of-type {
  font-size: var(--step-1);
  line-height: 1.55;
}

.post__body h2,
.post__body h3 {
  line-height: 1.25;
  letter-spacing: -0.01em;
  margin-block: 2.25rem 0.75rem;
  text-wrap: balance;
}

.post__body h2 { font-size: 1.5rem; }
.post__body h3 { font-size: 1.2rem; }

.post__body a {
  color: var(--color-accent);
  text-decoration-thickness: 1px;
  text-underline-offset: 0.15em;
}

.post__body a:hover {
  text-decoration-thickness: 2px;
}

.post__body ul,
.post__body ol {
  padding-left: 1.25rem;
}

.post__body li + li {
  margin-top: 0.4rem;
}

.post__body img,
.post__body video {
  max-width: 100%;
  height: auto;
  border-radius: 6px;
}

.post__body figure {
  margin-inline: 0;
}

.post__body figcaption {
  margin-top: 0.5rem;
  font-family: var(--font-ui);
  font-size: 0.85rem;
  color: var(--color-muted);
  text-align: center;
}

.post__body blockquote:not(.pullquote) {
  margin-inline: 0;
  padding-left: 1rem;
  border-left: 3px solid var(--color-rule);
  color: var(--color-muted);
  font-style: italic;
}

.post__body code {
  font-family: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  font-size: 0.9em;
  background: var(--color-quote-bg);
  padding: 0.15em 0.35em;
  border-radius: 4px;
}

.post__body pre {
  overflow-x: auto;
  padding: 1rem;
  border-radius: 6px;
  background: var(--color-quote-bg);
  line-height: 1.5;
}

.post__body pre code {
  background: none;
  padding: 0;
}

/* --------------------------------------------
   Pull quotes
   -------------------------------------------- */
.pullquote {
  margin: 2.5rem 0;
  padding: 1.5rem 1.75rem;
  background: var(--color-quote-bg);
  border-left: 4px solid var(--color-accent);
  border-radius: 0 8px 8px 0;
  font-size: var(--step-1);
  line-height: 1.4;
  font-style: italic;
  font-weight: 500;
  color: var(--color-text);
  text-wrap: balance;
}

.pullquote p {
  margin: 0;
}

/* Attribution / source line */
.pullquote cite {
  display: block;
  margin-top: 0.75rem;
  font-family: var(--font-ui);
  font-size: 0.85rem;
  font-style: normal;
  font-weight: 600;
  letter-spacing: 0.03em;
  text-transform: uppercase;
  color: var(--color-muted);
}

.pullquote cite::before {
  content: "— ";
}

/* Variant: centered, no background */
.pullquote--center {
  border-left: none;
  background: none;
  text-align: center;
  padding-inline: 0;
  font-size: 1.5rem;
}

/* Variant: large display quote */
.pullquote--display {
  border-left: none;
  background: none;
  padding-inline: 0;
  text-align: center;
  font-size: clamp(1.5rem, 1.1rem + 1.6vw, 2.1rem);
  font-weight: 600;
  font-style: normal;
  line-height: 1.3;
}

/* --------------------------------------------
   Footer / tags
   -------------------------------------------- */
.post__footer {
  margin-top: 3rem;
  padding-top: 1.5rem;
  border-top: 1px solid var(--color-rule);
  font-family: var(--font-ui);
  font-size: 0.9rem;
  color: var(--color-muted);
}

.tag {
  display: inline-block;
  margin-right: 0.4rem;
  padding: 0.2rem 0.6rem;
  border: 1px solid var(--color-rule);
  border-radius: 999px;
  text-decoration: none;
  color: inherit;
}

.tag:hover {
  border-color: var(--color-accent);
  color: var(--color-accent);
}

/* --------------------------------------------
   Accessibility
   -------------------------------------------- */
.post :focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 3px;
  border-radius: 2px;
}

@media (prefers-reduced-motion: reduce) {
  * {
    transition: none !important;
    animation: none !important;
  }
}
```

