  border-left: 3px solid #d1d5db;
  color: var(--muted-color);
  font-style: italic;
}

.post__body ul,
.post__body ol {
  margin: 0 0 1.5rem;
  padding-left: 1.5rem;
}

.post__body li { margin-bottom: 0.5rem; }

.post__body code {
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 0.875em;
  background: #f3f4f6;
  padding: 0.15em 0.4em;
  border-radius: 4px;
}

.post__body pre {
  background: #111827;
  color: #f9fafb;
  padding: 1.25rem;
  border-radius: 8px;
  overflow-x: auto;
  font-size: 0.9rem;
  line-height: 1.6;
}

.post__body pre code {
  background: none;
  padding: 0;
  color: inherit;
}

/* ---------- Pull Quote ---------- */
.pullquote {
  margin: 3rem 0;
  padding: 2rem 0;
  border-top: 3px solid var(--accent-color);
  border-bottom: 3px solid var(--accent-color);
  text-align: center;
}

.pullquote p {
  margin: 0;
  font-size: clamp(1.35rem, 3.5vw, 1.85rem);
  line-height: 1.4;
  font-style: italic;
  font-weight: 600;
  color: #111827;
  text-wrap: balance;
}

.pullquote cite {
  display: block;
  margin-top: 1rem;
  font-family: var(--font-ui);
  font-size: 0.875rem;
  font-style: normal;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--muted-color);
}

.pullquote cite::before {
  content: "— ";
}

/* ---------- Footer ---------- */
.post__footer {
  margin-top: 3rem;
  padding-top: 1.5rem;
  border-top: 1px solid #e5e7eb;
  font-family: var(--font-ui);
  font-size: 0.9rem;
  color: var(--muted-color);
}

/* ---------- Responsive ---------- */
@media (max-width: 600px) {
  .post {
    padding: 2.5rem 1.25rem 4rem;
  }

  .post__meta {
    font-size: 0.8125rem;
    gap: 0.375rem;
  }

  .pullquote {
    margin: 2.25rem 0;
    padding: 1.5rem 0;
  }
}
```

