  margin: 0 0 1.5rem;
  font-size: 1.5rem;
  font-weight: 600;
  text-align: center;
}

/* ---------- Fields ---------- */
.field {
  margin-bottom: 1.25rem;
}

.field__label {
  display: block;
  margin-bottom: 0.375rem;
  font-size: 0.875rem;
  font-weight: 500;
  color: #374151;
}

.field__input {
  width: 100%;
  padding: 0.75rem 0.875rem;
  font-size: 1rem;
  color: #111827;
  background: #fff;
  border: 1px solid #d1d5db;
  border-radius: 8px;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.field__input::placeholder {
  color: #9ca3af;
}

.field__input:hover {
  border-color: #9ca3af;
}

.field__input:focus {
  outline: none;
  border-color: #4f46e5;
  box-shadow: 0 0 0 3px rgba(79, 70, 229, 0.2);
}

/* ---------- Button ---------- */
.btn {
  width: 100%;
  padding: 0.8125rem 1rem;
  font-size: 1rem;
  font-weight: 600;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  transition: background-color 0.15s ease, transform 0.05s ease;
}

.btn--primary {
  background: #4f46e5;
  color: #fff;
}

.btn--primary:hover {
  background: #4338ca;
}

.btn--primary:active {
  transform: translateY(1px);
}

.btn--primary:focus-visible {
  outline: 3px solid rgba(79, 70, 229, 0.4);
  outline-offset: 2px;
}

.btn--primary:disabled {
  background: #a5b4fc;
  cursor: not-allowed;
}

/* ---------- Error state (add class to .field) ---------- */
.field--error .field__input {
  border-color: #dc2626;
}

.field--error .field__input:focus {
  box-shadow: 0 0 0 3px rgba(220, 38, 38, 0.2);
}

.field__error {
  margin: 0.375rem 0 0;
  font-size: 0.8125rem;
  color: #dc2626;
}
```

### Key details
- **`:focus` vs `:focus-visible`** — inputs get a soft ring; the button only shows an outline for keyboard users.
- **BEM-ish naming** (`.field__input`, `.btn--primary`) keeps styles easy to extend.
- **`box-sizing: border-box`** makes `width: 100%` include padding and borders, so inputs don't overflow.
- **Error state** is handled by adding `.field--error` to the wrapper plus an optional `.field__error` message.
- **Reduced motion** — if you want, add this to respect user preferences:

```css
@media (prefers-reduced-motion: reduce) {
  * {
    transition: none !important;
    animation: none !important;
  }
}
```

