  min-height: 100vh;
  display: grid;
  place-items: center;
  background: var(--color-bg);
  color: var(--color-text);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
}

/* ---------- Form container ---------- */
.login-form {
  width: 100%;
  max-width: 380px;
  padding: 2rem 1.75rem;
  background: var(--color-surface);
  border-radius: 12px;
  box-shadow: 0 10px 30px rgba(15, 23, 42, 0.08);
}

