  margin: 0 0 1.5rem;
  font-size: 1.5rem;
  font-weight: 600;
  text-align: center;
}

/* ---------- Fields ---------- */
.field {
  margin-bottom: 1.1rem;
}

.field__label {
  display: block;
  margin-bottom: 0.4rem;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--color-text);
}

.field__input {
  width: 100%;
  padding: 0.7rem 0.85rem;
  font-size: 1rem;
  color: var(--color-text);
  background: #fff;
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.field__input::placeholder {
  color: var(--color-muted);
}

/* Focus state (keyboard accessible) */
.field__input:focus {
  outline: none;
  border-color: var(--color-primary);
  box-shadow: 0 0 0 3px rgba(59, 91, 219, 0.2);
}

/* Invalid state — pair with :user-invalid or server-side errors */
.field__input:user-invalid {
  border-color: var(--color-error);
}

/* ---------- Submit button ---------- */
.login-form__submit {
  width: 100%;
  margin-top: 0.5rem;
  padding: 0.8rem 1rem;
  font-size: 1rem;
  font-weight: 600;
  color: #fff;
  background: var(--color-primary);
  border: none;
  border-radius: var(--radius);
  cursor: pointer;
  transition: background-color 0.15s ease, transform 0.05s ease;
}

.login-form__submit:hover {
  background: var(--color-primary-hover);
}

.login-form__submit:active {
  transform: translateY(1px);
}

.login-form__submit:focus-visible {
  outline: 3px solid rgba(59, 91, 219, 0.4);
  outline-offset: 2px;
}

.login-form__submit[disabled] {
  background: var(--color-muted);
  cursor: not-allowed;
}

/* ---------- Responsive ---------- */
@media (max-width: 420px) {
  .login-form {
    padding: 1.5rem 1.25rem;
    box-shadow: none;
  }
}
```

Key points:
- **Labels are real `<label for>` elements**, so clicking them focuses the input and screen readers announce it correctly.
- **Focus is visible** via `:focus` on inputs and `:focus-visible` on the button — never removed without a replacement.
- **`:user-invalid`** only styles fields the user has actually interacted with, avoiding red errors on first load.
- Layout uses `border-box` sizing and a `max-width` so it works on mobile without media-query fixes.

