```css
/* ---------- Design tokens ---------- */
:root {
  --color-bg:        #ffffff;
  --color-surface:   #f7f8fa;
  --color-text:      #1a1d21;
  --color-muted:     #5b6472;
  --color-border:    #e4e7ec;
  --color-primary:   #3b5bfd;
  --color-primary-d: #2a44d0;
  --header-height:   72px;
  --radius:          10px;
  --font: "Inter", system-ui, -apple-system, "Segoe UI", sans-serif;
}

/* ---------- Header shell ---------- */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--color-bg);
  border-bottom: 1px solid var(--color-border);
}

.header-inner {
  max-width: 1200px;
  margin-inline: auto;
  padding-inline: 24px;
  height: var(--header-height);
  display: flex;
  align-items: center;
  gap: 32px;
}

/* ---------- Logo ---------- */
.logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 1.25rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--color-text);
  text-decoration: none;
  flex-shrink: 0;
}

.logo img {
  height: 32px;
  width: auto;
  display: block;
}

/* ---------- Navigation ---------- */
.nav {
  flex: 1;
}

.nav-list {
  display: flex;
  align-items: center;
  gap: 4px;
  list-style: none;
  margin: 0;
  padding: 0;
}

.nav-link {
  display: inline-block;
  padding: 8px 14px;
  border-radius: 8px;
  color: var(--color-muted);
  font-size: 0.95rem;
  font-weight: 500;
  text-decoration: none;
  transition: color .18s ease, background-color .18s ease;
}

.nav-link:hover,
.nav-link:focus-visible {
  color: var(--color-text);
  background: var(--color-surface);
}

.nav-link[aria-current="page"] {
  color: var(--color-primary);
  background: color-mix(in srgb, var(--color-primary) 10%, transparent);
}

/* ---------- Actions / buttons ---------- */
.header-actions {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-shrink: 0;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: 42px;
  padding: 0 20px;
  border: 1px solid transparent;
  border-radius: var(--radius);
  font: inherit;
  font-size: 0.95rem;
  font-weight: 600;
  text-decoration: none;
  white-space: nowrap;
  cursor: pointer;
  transition: background-color .18s ease, border-color .18s ease,
              color .18s ease, transform .12s ease, box-shadow .18s ease;
}

.btn:active { transform: translateY(1px); }

.btn--primary {
  background: var(--color-primary);
  color: #fff;
  box-shadow: 0 1px 2px rgba(16, 24, 40, .08);
}
.btn--primary:hover {
  background: var(--color-primary-d);
  box-shadow: 0 6px 16px rgba(59, 91, 253, .28);
}

.btn--ghost {
  background: transparent;
  color: var(--color-text);
}
.btn--ghost:hover { background: var(--color-surface); }

.btn:focus-visible,
.nav-link:focus-visible,
.logo:focus-visible {
  outline: 2px solid var(--color-primary);
  outline-offset: 2px;
}

/* ---------- Mobile toggle (hidden on desktop) ---------- */
.nav-toggle {
  display: none;
  flex-direction: column;
  justify-content: center;
  gap: 5px;
  width: 42px;
  height: 42px;
  padding: 0 10px;
  background: none;
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  cursor: pointer;
}

.nav-toggle span {
  display: block;
  height: 2px;
  width: 100%;
  background: var(--color-text);
  border-radius: 2px;
  transition: transform .25s ease, opacity .2s ease;
}

/* ---------- Responsive ---------- */
@media (max-width: 860px) {
  .header-inner { gap: 16px; }

  .nav-toggle { display: flex; margin-left: auto; }

  .nav {
    position: absolute;
    inset: var(--header-height) 0 auto 0;
    background: var(--color-bg);
    border-bottom: 1px solid var(--color-border);
    padding: 12px 24px 20px;
    display: none;
  }

  .nav.is-open { display: block; }

  .nav-list {
    flex-direction: column;
    align-items: stretch;
    gap: 2px;
  }

  .nav-link {
    display: block;
    padding: 12px 14px;
    font-size: 1rem;
  }

  .header-actions { display: none; }

  /* Toggle → X animation */
  .nav-toggle[aria-expanded="true"] span:nth-child(1) { transform: translateY(7px) rotate(45deg); }
  .nav-toggle[aria-expanded="true"] span:nth-child(2) { opacity: 0; }
  .nav-toggle[aria-expanded="true"] span:nth-child(3) { transform: translateY(-7px) rotate(-45deg); }
}

@media (max-width: 420px) {
  .header-inner { padding-inline: 16px; }
}

/* ---------- Optional: translucent header on scroll ---------- */
.site-header.is-scrolled {
  background: color-mix(in srgb, var(--color-bg) 85%, transparent);
  backdrop-filter: blur(12px);
  box-shadow: 0 1px 12px rgba(16, 24, 40, .06);
}
```

Tiny JS to wire up the mobile toggle and scroll state:

```js
const toggle = document.querySelector('.nav-toggle');
const nav = document.querySelector('.nav');

toggle.addEventListener('click', () => {
  const open = nav.classList.toggle('is-open');
  toggle.setAttribute('aria-expanded', String(open));
});

const header = document.querySelector('.site-header');
addEventListener('scroll', () => {
  header.classList.toggle('is-scrolled', scrollY > 8);
});
```

