  box-shadow: 0 6px 16px rgba(59, 91, 253, 0.28);
  transform: translateY(-1px);
}

.btn:active { transform: translateY(0); }

/* ============ Focus visibility ============ */
a:focus-visible,
button:focus-visible {
  outline: 2px solid var(--color-focus);
  outline-offset: 2px;
  border-radius: var(--radius);
}

/* ============ Mobile toggle (hidden on desktop) ============ */
.nav-toggle {
  display: none;
  flex-direction: column;
  justify-content: center;
  gap: 5px;
  width: 42px;
  height: 42px;
  padding: 0 10px;
  background: none;
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  cursor: pointer;
}

.nav-toggle__bar {
  display: block;
  height: 2px;
  width: 100%;
  background: var(--color-text);
  border-radius: 2px;
  transition: transform 0.25s ease, opacity 0.2s ease;
}

/* ============ Responsive ============ */
@media (max-width: 860px) {
  .site-header__inner { gap: 16px; }

  .nav-toggle { display: flex; }

  /* Collapse nav + secondary action into a dropdown panel */
  .nav,
  .site-header__actions {
    position: absolute;
    top: var(--header-height);
    left: 0;
    right: 0;
    background: var(--color-bg);
    border-bottom: 1px solid var(--color-border);
    padding: 12px 24px 20px;
    display: none;
  }

  .nav { box-shadow: 0 12px 24px rgba(16, 24, 40, 0.08); }

  .site-header__actions {
    top: auto;
    border-bottom: 0;
    padding-top: 0;
    flex-direction: column;
    align-items: stretch;
  }

  .nav__list {
    flex-direction: column;
    align-items: stretch;
    gap: 2px;
  }

  .nav__link { padding: 12px 10px; font-size: 1rem; }
  .nav__link::after { display: none; }

  .btn { width: 100%; }

  /* Open state — toggled via [data-open] on the header */
  .site-header[data-open="true"] .nav,
  .site-header[data-open="true"] .site-header__actions {
    display: flex;
  }

  .site-header[data-open="true"] .nav-toggle__bar:nth-child(1) {
    transform: translateY(7px) rotate(45deg);
  }
  .site-header[data-open="true"] .nav-toggle__bar:nth-child(2) {
    opacity: 0;
  }
  .site-header[data-open="true"] .nav-toggle__bar:nth-child(3) {
    transform: translateY(-7px) rotate(-45deg);
  }
}

@media (max-width: 420px) {
  .logo__text { display: none; }
}

/* ============ Reduced motion ============ */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }
}
