.nav__link:focus-visible { color: var(--fg); }

/* Active / current page underline */
.nav__link[aria-current="page"] { color: var(--fg); }
.nav__link[aria-current="page"]::after {
  content: "";
  position: absolute;
  left: 0.25rem; right: 0.25rem; bottom: 0;
  height: 2px;
  background: var(--accent);
  border-radius: 2px;
}

/* ---------- Actions ---------- */
.site-header__actions {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  flex-shrink: 0;
}

/* ---------- Buttons ---------- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.6rem 1.1rem;
  font: inherit;
  font-size: 0.95rem;
  font-weight: 600;
  line-height: 1.2;
  border: 1px solid transparent;
  border-radius: var(--radius);
  cursor: pointer;
  white-space: nowrap;
  transition: background-color 0.18s ease, color 0.18s ease,
              border-color 0.18s ease, transform 0.12s ease;
}
.btn:active { transform: translateY(1px); }

.btn--primary {
  background: var(--accent);
  color: var(--accent-fg);
  box-shadow: 0 1px 2px rgb(16 24 40 / 0.08);
}
.btn--primary:hover { background: var(--accent-hover); }

.btn--ghost {
  background: transparent;
  color: var(--fg);
}
.btn--ghost:hover { background: #f2f3f5; }

/* ---------- Focus visibility ---------- */
:where(a, button):focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
  border-radius: 6px;
}

/* ---------- Mobile toggle (hidden on desktop) ---------- */
.nav-toggle {
  display: none;
  flex-direction: column;
  justify-content: center;
  gap: 5px;
  width: 42px; height: 42px;
  padding: 10px;
  background: none;
  border: 1px solid var(--border);
  border-radius: 8px;
  cursor: pointer;
}
.nav-toggle__bar {
  display: block;
  height: 2px;
  width: 100%;
  background: var(--fg);
  border-radius: 2px;
  transition: transform 0.25s ease, opacity 0.2s ease;
}

/* ---------- Responsive ---------- */
@media (max-width: 860px) {
  .nav-toggle { display: flex; }

  .nav {
    position: absolute;
    inset: var(--header-height) 0 auto 0;
    margin: 0;
    padding: 1rem var(--space) 1.5rem;
    background: var(--bg);
    border-bottom: 1px solid var(--border);
    box-shadow: 0 12px 24px rgb(16 24 40 / 0.06);
    display: none;
  }
  .nav.is-open { display: block; }

  .nav__list {
    flex-direction: column;
    align-items: stretch;
    gap: 0.25rem;
  }
  .nav__link {
    display: block;
    padding: 0.75rem 0.5rem;
    font-size: 1rem;
  }
  .nav__link[aria-current="page"]::after { display: none; }
  .nav__link[aria-current="page"] { color: var(--accent); }

  .site-header__actions .btn--ghost { display: none; }
}

/* ---------- Dark mode ---------- */
@media (prefers-color-scheme: dark) {
  :root {
    --bg:         #0e1116;
    --fg:         #e8eaed;
    --fg-muted:   #9aa4b2;
    --border:     #232830;
    --accent:     #7c74ff;
    --accent-hover:#8f88ff;
  }
  .btn--ghost:hover { background: #1b1f26; }
}
