  text-decoration: none;
  transition: color var(--transition), background-color var(--transition);
}

.site-nav__link:hover,
.site-nav__link:focus-visible {
  color: var(--color-text);
  background: rgba(16, 21, 31, 0.04);
}

/* Active page indicator */
.site-nav__link[aria-current="page"] {
  color: var(--color-text);
  font-weight: 600;
}

.site-nav__link[aria-current="page"]::after {
  content: "";
  position: absolute;
  left: 0.85rem;
  right: 0.85rem;
  bottom: 0.15rem;
  height: 2px;
  border-radius: 2px;
  background: var(--color-primary);
}

/* ============================================================
   CTA button
   ============================================================ */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.65rem 1.25rem;
  border: 1px solid transparent;
  border-radius: var(--radius-pill);
  font-size: 0.95rem;
  font-weight: 600;
  line-height: 1.2;
  text-decoration: none;
  white-space: nowrap;
  cursor: pointer;
  transition: background-color var(--transition), color var(--transition),
              box-shadow var(--transition), transform var(--transition);
}

.btn--primary {
  background: var(--color-primary);
  color: #fff;
  box-shadow: var(--shadow-sm);
}

.btn--primary:hover {
  background: var(--color-primary-hover);
  box-shadow: var(--shadow-md);
}

.btn--primary:active { transform: translateY(1px); }

.site-header__cta { flex-shrink: 0; }

/* ============================================================
   Mobile toggle
   ============================================================ */
.nav-toggle {
  display: none;
  flex-direction: column;
  justify-content: center;
  gap: 5px;
  width: 44px;
  height: 44px;
  padding: 10px;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  background: transparent;
  cursor: pointer;
}

.nav-toggle__bar {
  display: block;
  height: 2px;
  width: 100%;
  border-radius: 2px;
  background: var(--color-text);
  transition: transform var(--transition), opacity var(--transition);
}

/* ============================================================
   Focus visibility
   ============================================================ */
:where(a, button):focus-visible {
  outline: 2px solid var(--color-focus);
  outline-offset: 2px;
  border-radius: var(--radius-sm);
}

/* ============================================================
   Responsive
   ============================================================ */
@media (max-width: 860px) {
  .nav-toggle { display: flex; margin-inline-start: auto; }

  .site-nav {
    position: absolute;
    inset: var(--header-height) 0 auto 0;
    margin: 0;
    padding: 0.75rem var(--space-inline) 1.25rem;
    background: var(--color-bg);
    border-bottom: 1px solid var(--color-border);
    box-shadow: var(--shadow-md);

    /* Hidden by default */
    display: none;
  }

  .site-nav.is-open { display: block; }

  .site-nav__list {
    flex-direction: column;
    align-items: stretch;
    gap: 0.15rem;
  }

  .site-nav__link {
    padding: 0.85rem 0.75rem;
    font-size: 1rem;
    border-radius: var(--radius-sm);
  }

  .site-nav__link[aria-current="page"]::after { display: none; }

  .site-header__cta {
    order: 3;
    padding: 0.55rem 1rem;
  }
}

/* Very small screens: stack CTA under the logo row */
@media (max-width: 420px) {
  .site-header__inner { flex-wrap: wrap; row-gap: 0.75rem; }
  .site-header__cta { order: 2; }
}

/* ============================================================
   Dark mode
   ============================================================ */
@media (prefers-color-scheme: dark) {
  :root {
    --color-bg: #0d1117;
    --color-surface: rgba(13, 17, 23, 0.8);
    --color-text: #e8ecf3;
    --color-text-muted: #9aa4b2;
    --color-border: #232a35;
    --color-primary: #6b86ff;
    --color-primary-hover: #8399ff;
  }

  .site-nav { background: var(--color-bg); }
  .site-nav__link:hover { background: rgba(255, 255, 255, 0.06); }
}

/* ============================================================
   Reduced motion
   ============================================================ */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }
}
