  box-shadow: 0 4px 12px rgb(59 91 253 / 0.28);
}

.btn--primary:active { transform: translateY(0); }

/* ---------- Focus visibility (accessibility) ---------- */
a:focus-visible,
button:focus-visible,
label:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
  border-radius: var(--radius);
}

/* ---------- Mobile toggle ---------- */
.nav-toggle { display: none; }

.nav-toggle__label {
  display: none;
  width: 44px;
  height: 44px;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  border-radius: var(--radius);
}

.nav-toggle__bar,
.nav-toggle__bar::before,
.nav-toggle__bar::after {
  display: block;
  width: 22px;
  height: 2px;
  background: var(--fg);
  border-radius: 2px;
  transition: transform var(--transition), opacity var(--transition);
}

.nav-toggle__bar { position: relative; }
.nav-toggle__bar::before,
.nav-toggle__bar::after { content: ""; position: absolute; left: 0; }
.nav-toggle__bar::before { top: -7px; }
.nav-toggle__bar::after  { top: 7px; }

/* ---------- Responsive ---------- */
@media (max-width: 860px) {
  .nav-toggle__label { display: inline-flex; }

  .nav {
    position: absolute;
    inset: var(--header-height) 0 auto 0;
    flex-direction: column;
    align-items: stretch;
    gap: 1rem;
    padding: 1.25rem 1.5rem 1.75rem;
    background: var(--bg);
    border-bottom: 1px solid var(--border);
    box-shadow: 0 12px 24px rgb(0 0 0 / 0.06);

    /* Hidden by default */
    display: none;
  }

  .nav__list {
    flex-direction: column;
    align-items: stretch;
    gap: 0.25rem;
  }

  .nav__link {
    display: block;
    padding: 0.75rem 0.5rem;
    font-size: 1rem;
  }

  .btn--primary { width: 100%; }

  /* Open state via the hidden checkbox */
  .nav-toggle:checked ~ .nav { display: flex; }

  /* Animate the hamburger into an X */
  .nav-toggle:checked ~ .nav-toggle__label .nav-toggle__bar { background: transparent; }
  .nav-toggle:checked ~ .nav-toggle__label .nav-toggle__bar::before {
    transform: translateY(7px) rotate(45deg);
  }
  .nav-toggle:checked ~ .nav-toggle__label .nav-toggle__bar::after {
    transform: translateY(-7px) rotate(-45deg);
  }
}

/* ---------- Reduced motion ---------- */
@media (prefers-reduced-motion: reduce) {
  * { transition-duration: 0.01ms !important; animation-duration: 0.01ms !important; }
}
