  list-style: none;
  margin: 0;
  padding: 0;
}

.main-nav a {
  display: block;
  padding: 10px 14px;
  border-radius: var(--radius);
  color: var(--text-muted);
  font-size: 0.95rem;
  font-weight: 500;
  text-decoration: none;
  transition: background-color var(--transition), color var(--transition);
}

.main-nav a:hover,
.main-nav a:focus-visible {
  color: var(--text);
  background: #f3f4f6;
}

.main-nav a.active {
  color: var(--accent);
  background: rgba(79, 70, 229, 0.08);
}

/* ---------- Actions / Buttons ---------- */
.header-actions {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-shrink: 0;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 10px 20px;
  border-radius: var(--radius);
  border: 1px solid transparent;
  font-size: 0.95rem;
  font-weight: 600;
  text-decoration: none;
  cursor: pointer;
  white-space: nowrap;
  transition: background-color var(--transition), color var(--transition),
    border-color var(--transition), transform var(--transition);
}

.btn:active {
  transform: translateY(1px);
}

.btn-primary {
  background: var(--accent);
  color: #fff;
}

.btn-primary:hover,
.btn-primary:focus-visible {
  background: var(--accent-hover);
}

.btn-ghost {
  background: transparent;
  color: var(--text);
}

.btn-ghost:hover,
.btn-ghost:focus-visible {
  background: #f3f4f6;
}

/* ---------- Mobile toggle ---------- */
.nav-toggle {
  display: none;
  flex-direction: column;
  justify-content: center;
  gap: 5px;
  width: 40px;
  height: 40px;
  padding: 0 8px;
  background: none;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  cursor: pointer;
}

.nav-toggle span {
  display: block;
  height: 2px;
  width: 100%;
  background: var(--text);
  border-radius: 2px;
  transition: transform var(--transition), opacity var(--transition);
}

/* ---------- Responsive ---------- */
@media (max-width: 860px) {
  .nav-toggle {
    display: flex;
    margin-left: auto;
  }

  .main-nav {
    position: absolute;
    top: var(--header-height);
    left: 0;
    right: 0;
    flex: none;
    background: var(--bg);
    border-bottom: 1px solid var(--border);
    box-shadow: 0 10px 20px rgba(0, 0, 0, 0.06);
    display: none;
  }

  .main-nav.open {
    display: block;
  }

  .main-nav ul {
    flex-direction: column;
    align-items: stretch;
    gap: 0;
    padding: 8px 16px 16px;
  }

  .main-nav a {
    padding: 12px;
    border-radius: var(--radius);
  }

  .header-actions .btn-ghost {
    display: none;
  }
}

@media (max-width: 480px) {
  .header-actions .btn-primary {
    padding: 9px 14px;
    font-size: 0.9rem;
  }
}

/* ---------- Accessibility ---------- */
:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}
```

## Optional: JS for the mobile toggle

```js
const toggle = document.querySelector('.nav-toggle');
const nav = document.querySelector('.main-nav');

toggle.addEventListener('click', () => {
  const open = nav.classList.toggle('open');
  toggle.setAttribute('aria-expanded', open);
});
```

**Key features:** sticky positioning, flexbox layout with the nav auto-centering, hover/focus states, a pure-CSS hamburger that expands on mobile, and `:focus-visible` outlines for keyboard accessibility. Swap the color tokens in `:root` to retheme the whole header.

Here's a clean, responsive site header with a logo, navigation links, and a call-to-action button:

```html
<header class="site-header">
  <div class="container header-inner">
    <a href="/" class="logo">
      <img src="logo.svg" alt="Acme Inc.">
    </a>

    <nav class="main-nav" aria-label="Main navigation">
      <ul>
        <li><a href="/about">About</a></li>
        <li><a href="/services">Services</a></li>
        <li><a href="/blog">Blog</a></li>
        <li><a href="/contact">Contact</a></li>
      </ul>
    </nav>

    <a href="/signup" class="cta-button">Get Started</a>

    <button class="menu-toggle" aria-label="Toggle menu" aria-expanded="false">
      <span></span><span></span><span></span>
    </button>
  </div>
</header>
```

```css
/* ---------- Base ---------- */
*,
*::before,
*::after {
  box-sizing: border-box;
}

:root {
  --color-primary: #2563eb;
  --color-primary-dark: #1d4ed8;
  --color-text: #1f2937;
  --color-muted: #6b7280;
  --color-border: #e5e7eb;
  --header-height: 72px;
}

body {
  margin: 0;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  color: var(--color-text);
}

/* ---------- Header ---------- */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: #fff;
  border-bottom: 1px solid var(--color-border);
}

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}

.header-inner {
  display: flex;
  align-items: center;
  gap: 32px;
  min-height: var(--header-height);
}

/* ---------- Logo ---------- */
.logo {
  display: flex;
  align-items: center;
  flex-shrink: 0;
  font-size: 1.35rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--color-text);
  text-decoration: none;
}

.logo img {
  height: 36px;
  width: auto;
}

/* ---------- Navigation ---------- */
.main-nav {
  margin-left: auto;
}

.main-nav ul {
  display: flex;
  align-items: center;
  gap: 28px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.main-nav a {
  position: relative;
  color: var(--color-muted);
  font-size: 0.95rem;
  font-weight: 500;
  text-decoration: none;
  transition: color 0.2s ease;
}

.main-nav a:hover,
.main-nav a:focus-visible,
.main-nav a[aria-current="page"] {
  color: var(--color-text);
}

/* Underline animation on hover */
.main-nav a::after {
  content: "";
  position: absolute;
  left: 0;
  bottom: -6px;
  width: 100%;
  height: 2px;
  background: var(--color-primary);
  transform: scaleX(0);
  transform-origin: left;
  transition: transform 0.25s ease;
}

.main-nav a:hover::after,
.main-nav a:focus-visible::after,
.main-nav a[aria-current="page"]::after {
  transform: scaleX(1);
}

/* ---------- CTA Button ---------- */
.cta-button {
  display: inline-block;
  padding: 10px 20px;
  background: var(--color-primary);
  color: #fff;
  font-size: 0.95rem;
  font-weight: 600;
  text-decoration: none;
  border-radius: 8px;
  white-space: nowrap;
  transition: background-color 0.2s ease, transform 0.2s ease,
    box-shadow 0.2s ease;
}

.cta-button:hover {
  background: var(--color-primary-dark);
  transform: translateY(-1px);
  box-shadow: 0 4px 12px rgba(37, 99, 235, 0.3);
}

.cta-button:active {
  transform: translateY(0);
}

/* ---------- Mobile Menu Toggle ---------- */
.menu-toggle {
  display: none;
  flex-direction: column;
  justify-content: center;
  gap: 5px;
  width: 42px;
  height: 42px;
  padding: 10px;
  background: none;
  border: 1px solid var(--color-border);
  border-radius: 8px;
  cursor: pointer;
}

.menu-toggle span {
  display: block;
  height: 2px;
  width: 100%;
  background: var(--color-text);
  border-radius: 2px;
}

/* ---------- Responsive ---------- */
@media (max-width: 860px) {
  .header-inner {
    flex-wrap: wrap;
    gap: 16px;
    padding-top: 12px;
    padding-bottom: 12px;
  }

  .menu-toggle {
    display: flex;
    margin-left: auto;
    order: 3;
  }

  .cta-button {
    order: 2;
  }

  .main-nav {
    order: 4;
    flex-basis: 100%;
    margin-left: 0;
    display: none;
  }

  .main-nav.is-open {
    display: block;
  }

  .main-nav ul {
    flex-direction: column;
    align-items: stretch;
    gap: 0;
    padding-top: 8px;
  }

  .main-nav a {
    display: block;
    padding: 12px 0;
    border-top: 1px solid var(--color-border);
  }

  .main-nav a::after {
    display: none;
  }
}
```

Optional JavaScript to toggle the mobile menu:

```html
<script>
  const toggle = document.querySelector('.menu-toggle');
  const nav = document.querySelector('.main-nav');

  toggle.addEventListener('click', () => {
    const isOpen = nav.classList.toggle('is-open');
    toggle.setAttribute('aria-expanded', isOpen);
  });
</script>
```

**Key features:** sticky positioning, accessible focus states, hover underline animation, a responsive hamburger menu under 860px, and a `.is-open` class for mobile navigation.
